bool Read_GetMapOptionsResult(const WasmValue& input, GetMapOptionsResult& output, NativeCallStorage& storage, std::string& error)
{
	const auto* record = std::get_if<WasmValueRecord>(&input.storage);
	if (record == nullptr) { error = "Wasm argument is not a record"; return false; }
	const auto* value_keys = FindRecordField(*record, "keys", error);
	if (value_keys == nullptr) return false;
	const auto* list_keys = std::get_if<WasmValueList>(&(*value_keys).storage);
	if (list_keys == nullptr) { error = "Wasm argument is not a list"; return false; }
	auto& native_keys = storage.Make<std::vector<std::string>>();
	native_keys.reserve(list_keys->size());
	for (const auto& item : *list_keys) {
		std::string item_value{};
		auto& stored_string_item_value = storage.Make<std::string>();
		if (!ReadString(item, stored_string_item_value, error)) { return false; }
		item_value = stored_string_item_value.c_str();
		native_keys.push_back(std::move(item_value));
	}
	auto& pointers_keys = storage.Make<std::vector<const char*>>();
	pointers_keys.reserve(native_keys.size());
	for (const auto& item : native_keys) pointers_keys.push_back(item.c_str());
	output.keys = pointers_keys.data();
	if (!AssignCount(list_keys->size(), output.count, error)) { return false; }
	return true;
}

